INSERT INTO public.email_templates (id, name, subject, body_html, pdf_config, is_archived, created_at, updated_at) VALUES (14, 'Honorary Certificate Template', 'Congratulations {donorName}! Your Honorary Certificate from OpenmindProjects', '<h3>Dear {donorName},</h3><p>Congratulations on unlocking and claiming your milestone reward: <strong>{milestoneLabel}</strong>!</p><p>Your ongoing support enables us to build sustainable community programs and training camps. We are honored to have you as part of our journey.</p><p>Please find your official honorary certificate attached to this email.</p><p>Best regards,<br>The OpenmindProjects Team</p>', '{"fields": [{"x": 200, "y": 120, "type": "text", "color": "#4285f4", "value": "Honorary Certificate", "fontSize": 32}, {"x": 260, "y": 170, "type": "text", "color": "#6b7280", "value": "of Appreciation", "fontSize": 20}, {"x": 100, "y": 260, "type": "text", "color": "#202124", "value": "This certificate is proudly presented to:", "fontSize": 14}, {"x": 100, "y": 310, "type": "text", "color": "#202124", "value": "{donorName}", "fontSize": 28}, {"x": 100, "y": 390, "type": "text", "color": "#6b7280", "value": "In recognition of unlocking the OMP milestone objective:", "fontSize": 12}, {"x": 100, "y": 420, "type": "text", "color": "#4285f4", "value": "{milestoneLabel}", "fontSize": 18}, {"x": 100, "y": 490, "type": "text", "color": "#9ca3af", "value": "Awarded on: {date}", "fontSize": 11}, {"x": 100, "y": 100, "type": "text", "color": "#202124", "value": "", "fontSize": 14}], "backgroundImage": "data:image/png;base64,"}', false, '2026-07-03 08:41:57.271', '2026-07-03 09:34:03.426');
