INSERT INTO public.projects_detail (id, project_name, details, status, image_url, funding_goal, funded_amount) VALUES (70, 'Train The Trainer Camp', 'A 3-month on-site camp for Southeast Asian youth (Thailand, Myanmar and Laos) building critical thinking leaders. Focuses on 21st-century skills: problem-solving, confidence, teamwork, and motivation. Themes cover SDGs, digital/AI literacy, marketing, and social impact.', 'ACTIVE', NULL, 5000000, 1875000);
INSERT INTO public.projects_detail (id, project_name, details, status, image_url, funding_goal, funded_amount) VALUES (71, 'Active Learning Camp', 'An intensive, hands-on innovation program equipping youth with AI, digital, and problem-solving skills through immersive 4–7 day camps and mentorship. Each camp empowers roughly 60 participants to develop 5–10 project prototypes targeting local environmental, civic, or business challenges. Following the camp, youth leverage the "OpenSkills" platform for advanced learning pathways, portfolio building, and continuous guidance to turn ideas into real solutions.', 'ACTIVE', NULL, 3000000, 1200000);
INSERT INTO public.projects_detail (id, project_name, details, status, image_url, funding_goal, funded_amount) VALUES (72, 'Openmind.Travel', 'A hands-on innovation program equips underprivileged Thai youth with digital, problem-solving, marketing, and English skills via 10-day camps. Forty participants design local community tourism plans to transform villages into self-reliant hotspots. Post-camp, youth use the "OpenSkills" platform for advanced learning and marketing mentorship. These community initiatives are showcased on the "Openmind Travel" platform and integrated into "Openmind Tours," an organized group travel initiative launching this year to give travelers immersive rural experiences.', 'ACTIVE', NULL, 4000000, 2400000);


