INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('a6fea187-c50a-4a33-a9f7-1e888c22c777', 'welcome_headline', 'Empower Communities, Transform Lives', 'WELCOME', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('242a4219-8892-433c-bbc3-ec9768cfb97a', 'welcome_subheadline', 'Your monthly donation creates lasting impact through sustainable projects worldwide', 'WELCOME', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('54bae320-6104-48f6-a7d0-7bb436570aea', 'welcome_hero_intro', 'By becoming a monthly donor, you join a movement of changemakers who believe in consistent, long-term impact. Your contribution — no matter the size — helps us plan ahead, scale our projects, and deliver measurable results to the communities we serve.

10% of all donations go into our community "Piggy Banks," where you and fellow donors vote on which projects receive additional funding boosts. Together, we decide where your impact grows.', 'WELCOME', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('07a2bf51-d975-4b5e-8dbf-e129b4185501', 'projects_label', 'Where Your **Money** Goes', 'ACTIVE_PROJECTS', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('1801dc49-2b7d-437d-8444-4faf3c316067', 'projects_title', 'Active Projects', 'ACTIVE_PROJECTS', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('8005af87-68e3-4803-a1cc-db746e3fa2d9', 'projects_intro', 'Your donations directly fund these community-driven initiatives. Track progress and see the real impact of your contribution.', 'ACTIVE_PROJECTS', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('8a95cce4-50e9-4ebd-b9da-e2ab5b986538', 'boxes_label', 'Make an **Impact**', 'DONATION_BOXES', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('d9d61365-4706-43b9-8163-150fdfcf6653', 'boxes_title', 'Choose Your Donation', 'DONATION_BOXES', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('445138b7-3451-4a32-9611-93a3f24de2a2', 'boxes_cta', 'Select a plan that works for you. Every contribution, big or small, helps fund community projects and create lasting change.', 'DONATION_BOXES', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('19565a9f-f475-4124-89e3-45cf89067fb6', 'tiers_label', 'Your **Benefits**', 'DONATION_TIERS', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('b4eca90b-83df-4a5c-886b-04aeacff8d6e', 'tiers_title', 'Donation Tiers', 'DONATION_TIERS', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('0e8b29ba-b611-40eb-9fe2-c3cdb5ff1092', 'tiers_intro', 'Our tiers ensure transparency and show how every dollar level supports specific community goals.', 'DONATION_TIERS', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('b0d814ec-3e5b-43a8-845f-8ba5be3ef5e3', 'roadmap_label', 'Monthly **Rewards**', 'DONATION_ROADMAP', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('bf3eef83-8035-454a-860d-c3665dc7f8bb', 'roadmap_title', 'Monthly Donation Roadmap', 'DONATION_ROADMAP', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('aebae209-a0e9-432d-93c9-0703c872b414', 'roadmap_intro', 'Track the path of your donation from initial funding to on-the-ground project deployment.', 'DONATION_ROADMAP', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('0749a93a-1711-4700-b75d-a7d6d1c91715', 'impact_label', 'One-Time **Objectives**', 'TANGIBLE_IMPACT', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('c9b3547b-5ac6-4016-9991-e5953a33fed8', 'impact_title', 'Tangible Impact Objectives', 'TANGIBLE_IMPACT', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('7da30e85-ef44-4066-8b67-d9826acc7726', 'impact_intro', 'We focus on clear, measurable impact metrics. See what achievements our donor community has unlocked.', 'TANGIBLE_IMPACT', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('5b7160f3-2772-4751-8edd-7f8b932d4300', 'footer_brand_name', '**OpenmindProjects**', 'FOOTER', '2026-06-26 09:08:15.149');
INSERT INTO public.site_text (id, key, value, section, updated_at) VALUES ('df5d46bd-a6ad-4e19-841b-016890c137e0', 'footer_brand_desc', 'Building stronger communities through sustainable development initiatives.', 'FOOTER', '2026-06-26 09:08:15.149');
