INSERT INTO public.tiers (id, tier_level, name, min_amount, max_amount, is_auto_applied_by_sum, perks) VALUES (79, 1, 'Regular', 1, 84, true, '["Monthly updates from our newsletter", "Invitation to \"OMP''s yearly impact\" yearly zoom event", "Monthly seed coupons for voting based on the donated amount (1 seed = $1)", "Access to OMP group tours at a discounted rate (the real price without the middlemen)"]');
INSERT INTO public.tiers (id, tier_level, name, min_amount, max_amount, is_auto_applied_by_sum, perks) VALUES (80, 2, 'Shareholder', 85, 169, true, '["All Regular tier perks", "Quarter meetings: progression and behind the scenes — your opinions shape marketing research", "Special voting to create a campaign shown on the platform, with monthly aid from OMP for half a year from the second piggy bank", "Every $10 above $75 grants an additional vote", "Voting on small things like design for camp t-shirts and more"]');
INSERT INTO public.tiers (id, tier_level, name, min_amount, max_amount, is_auto_applied_by_sum, perks) VALUES (81, 3, 'Patron', 170, NULL, true, '["All Shareholder tier perks", "Your name on the back of camp t-shirts in the \"sponsors\" section", "Personal thank-you on our social media — quarterly name posts and video shout-outs"]');
INSERT INTO public.tiers (id, tier_level, name, min_amount, max_amount, is_auto_applied_by_sum, perks) VALUES (84, 44, 'VIP Patron', 0, NULL, false, '"[\"Access to VIP lounge\"]"');
