INSERT INTO public.website_content (id, head, subtitle, body, version, updated_at) VALUES (23, 'Empower Communities, Transform Lives', 'Your monthly donation creates lasting impact through sustainable projects worldwide', 'By becoming a monthly donor, you join a movement of changemakers who believe in consistent, long-term impact. Your contribution — no matter the size — helps us plan ahead, scale our projects, and deliver measurable results to the communities we serve.

10% of all donations go into our community "Piggy Banks," where you and fellow donors vote on which projects receive additional funding boosts. Together, we decide where your impact grows.', 1, '2026-06-26 09:08:15.134');


